import React, { createContext, useState } from 'react';

export const DragDropContext = createContext(null);

export default function DragDropProvider({ children }) {
  const [draggedItem, setDraggedItem] = useState(null);

  const startDrag = (item) => setDraggedItem(item);
  const endDrag = () => setDraggedItem(null);

  return (
    <DragDropContext.Provider value={{ draggedItem, startDrag, endDrag }}>
      {children}
    </DragDropContext.Provider>
  );
}
